def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_last = opp[-1]
    my_last = me[-1]

    opp_coop = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_coop
    my_d = sum(1 for a in me if a == 'D')
    opp_coop_rate = opp_coop / n

    opp_consec_D = 0
    for a in reversed(opp):
        if a == 'D':
            opp_consec_D += 1
        else:
            break
    my_consec_D = 0
    for a in reversed(me):
        if a == 'D':
            my_consec_D += 1
        else:
            break

    # Early game: probe with a defection, ensure at least two defections by round 10.
    if n < 10:
        if n == 1:
            return 'D'
        if n == 9 and my_d < 2:
            return 'D'
        if opp_last == 'C':
            return 'C'
        else:
            if opp_consec_D == 1:
                return 'C'
            else:
                if my_consec_D >= 1 and opp_consec_D >= 2:
                    return 'C' if rng.random() < 0.3 else 'D'
                return 'D'

    # Late game: exploit an opponent that never retaliated to our defections.
    if my_d >= 2 and opp_d == 0:
        if rng.random() < 0.85:
            return 'D'
        else:
            return 'C'

    # Against a very defective opponent, defect almost always.
    if opp_coop_rate < 0.2:
        if my_consec_D >= 1 and opp_consec_D >= 1:
            if rng.random() < 0.05:
                return 'C'
        return 'D'

    # Forgiving tit-for-tat core.
    if opp_last == 'C':
        return 'C'
    else:
        if opp_consec_D == 1:
            return 'C'
        else:
            if my_consec_D >= 1 and opp_consec_D >= 2:
                if rng.random() < 0.3:
                    return 'C'
            return 'D'
